package org.sleepwell.app;
import android.widget.*;import java.util.function.BooleanSupplier;
/** Same actual touch/physics controller in a ringing routine and silent local preview. */
final class JumpTask implements AutoCloseable {
 final JumpCheckpoint checkpoint;final JumpGame game;final JumpTimeline.Port timeline;final BooleanSupplier current;final Runnable complete,fallback;final JumpView view;final TextView status;final Button play,jump;boolean closed,running,delivered;long last;
 JumpTask(LinearLayout body,android.content.SharedPreferences prefs,String run,int unit,int round,BooleanSupplier current,Runnable complete,Runnable fallback){this.current=current;this.complete=complete;this.fallback=fallback;checkpoint=JumpCheckpoint.open(prefs,run,unit,round);game=new JumpGame(run,unit,round,checkpoint.cleared);timeline=JumpTimeline.factory.create();Design.text(body,"Jump over three hurdles",21,600,Design.INK);Design.text(body,"Tap the scene or Jump as a hurdle approaches. Cleared hurdles stay saved.",13,400,Design.MUTED);Design.space(body,12);view=new JumpView(body.getContext(),game,this::tap);body.addView(view,new LinearLayout.LayoutParams(-1,-2));status=Design.text(body,"Press Start game when ready",13,500,Design.BROWN);status.setContentDescription("Jump game status");status.setAccessibilityLiveRegion(android.view.View.ACCESSIBILITY_LIVE_REGION_POLITE);play=Design.button(body,game.cleared>0?"Resume game":"Start game",true,this::toggle);play.setContentDescription("Start or pause jump game");jump=Design.button(body,"Jump",false,this::tap);jump.setEnabled(false);Design.button(body,"Use Math instead",false,this::chooseMath);if(checkpoint.math){status.setText("Math alternative selected");play.setEnabled(false);}}
 boolean live(){return !closed&&!delivered&&current.getAsBoolean()&&checkpoint.owns();}
 void toggle(){if(!live()||checkpoint.math)return;if(running){pause("Paused · cleared hurdles are saved");return;}if(game.complete()){finish();return;}game.retry();try{timeline.cancel();last=timeline.now();running=true;jump.setEnabled(true);play.setText("Pause game");status.setText("Tap Jump before the hurdle reaches the orb");timeline.request(frame);}catch(RuntimeException failure){pause("Game timing is unavailable. Retry or use Math.");}}
 void tap(){if(!live()||!running)return;step();if(running&&game.jump())view.invalidate();}
 final Runnable frame=new Runnable(){public void run(){if(!running||closed)return;if(!live()){pause("Paused · open the current task to continue");return;}step();if(running)try{timeline.request(this);}catch(RuntimeException failure){pause("Game timing is unavailable. Retry or use Math.");}}};
 private void step(){if(!live()||!running)return;try{long now=timeline.now(),elapsed=now-last;if(elapsed<0||elapsed>250){pause("Paused after an interruption · resume when ready");return;}last=now;int before=game.cleared;for(long left=elapsed;left>0&&!game.crashed&&!game.complete();){long n=Math.min(100,left);game.advance(n);left-=n;}view.invalidate();if(game.cleared!=before){if(!checkpoint.save(game.cleared)){pause("Progress could not be saved. Reopen this task or use Math.");return;}status.setText(game.cleared+" of "+JumpGame.TARGET+" hurdles cleared");}if(game.crashed){pause("Hurdle touched · retry this obstacle");play.setText("Retry obstacle");}else if(game.complete())finish();}catch(RuntimeException failure){pause("Game is unavailable. Retry or use Math.");}}
 private void finish(){if(!live()||!game.complete())return;if(!checkpoint.save(game.cleared)){pause("Completion could not be saved. Retry or use Math.");return;}pause("All hurdles cleared");if(live()){delivered=true;complete.run();}}
 private void pause(String message){running=false;try{timeline.cancel();}catch(RuntimeException ignored){}jump.setEnabled(false);play.setText("Resume game");status.setText(message);}
 private void chooseMath(){if(!live())return;if(!checkpoint.fallback()){status.setText("Math alternative could not be saved. Try again.");return;}close();fallback.run();}
 @Override public void close(){if(closed)return;closed=true;running=false;try{timeline.cancel();}catch(RuntimeException ignored){}jump.setEnabled(false);}
}
